steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        teams(name: \"Mobile\") {
          nodes {
            id
            name
            key
          }
        }
        users(filter: { name: { contains: \"Priya Nair\" } }) {
          nodes {
            id
            name
            email
          }
        }
      }
    "
  }'
